javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
  const selectedLabel = api.item.value.label;
  if (!selectedLabel) return;

  // Get English label
  const engLabel = api.state.reverseTranslations[selectedLabel];
  if (!engLabel) return;

  // Get navigation config
  const navConfig = api.state.tabToListMap[engLabel];
  if (!navConfig) return;

  if (navConfig.navigateTo === "list") {
    return {
      route: "list",
      params: {
        listId: navConfig.path
      },
      navigationOptions: {
        replace: false
      }
    };
  }
  else if (navConfig.navigateTo === "page") {
    return {
      route: navConfig.path
    };
  }
  else {
    return {
      route: "list",
      fields: null,
      params: undefined,
      redirect: null,
      passiveNavigation: null,
      title: null,
      multiInstField: null,
      targetRoute: null,
      external: null,
      navigationOptions: null
    };
  }
})

